View matches with regular expressions

str_view(c("banana", "bananana", "bana", "banabanana"), "ba(na){1,2}")

[1] │ &lt;banana&gt;
[2] │ &lt;banana&gt;na
[3] │ &lt;bana&gt;
[4] │ &lt;bana&gt;&lt;banana&gt;



str_view_all(c("banana", "bananana", "bana", "banabanana"), "ba(na){1,2}")

[1] │ &lt;banana&gt;
[2] │ &lt;banana&gt;na
[3] │ &lt;bana&gt;
[4] │ &lt;bana&gt;&lt;banana&gt;

